css:
.qb-quote { font-family: sans-serif; background: #1a1a2e; color: #e8e8e8; border: 1px solid #0090ff; border-radius: 12px; padding: 16px; margin: 12px 0; }
.qb-site-header { display: flex; justify-content: space-between; font-size: 0.8em; color: #0090ff; margin-bottom: 10px; }
.qb-quote-text { font-size: 1.05em; line-height: 1.5; white-space: pre-wrap; }
.qb-author { text-align: right; font-style: italic; color: #aaa; margin-top: 8px; }
.qb-rating { margin-top: 8px; color: #ffd54f; font-weight: bold; }
.qb-meta { margin-top: 6px; font-size: 0.8em; color: #888; }
.qb-source-url { margin-top: 8px; font-size: 0.8em; }
.qb-source-url a { color: #0090ff; }
.qb-branding { margin-top: 10px; font-size: 0.75em; color: #666; text-align: center; }
